	addMass(ctx, mass, palette.tone3, { enterDY: height * .1 });
	addFaceRuling(ctx, [
		apexX,
		apexY,
		width + bleed,
		height + bleed,
		apexX + width * .24,
		height + bleed
	], 229);
	addSurveyLines(ctx, 3);
