const drawContourAtlas = ({ target, radius, seed, primary, secondary }) => {
	const steps = 48;
	for (let ring = 0; ring < 8; ring += 1) {
		const baseRadius = radius * (.16 + ring * .075);
		for (let step = 0; step <= steps; step += 1) {
			const angle = step / steps * Math.PI * 2;
			const ripple = Math.sin(angle * 3 + seed * .07 + ring) * radius * .018 + Math.cos(angle * 5 - seed * .03 + ring * .7) * radius * .012;
			const x = Math.cos(angle) * (baseRadius + ripple) + Math.sin(ring * 1.7) * radius * .055;
			const y = Math.sin(angle) * (baseRadius + ripple) * .72 + Math.cos(ring * 1.3) * radius * .035;
			if (step === 0) target.moveTo(x, y);
			else target.lineTo(x, y);
		}
		target.stroke({
			color: ring % 3 === 0 ? secondary : primary,
			width: ring % 3 === 0 ? 2 : 1,
			alpha: .2 + ring * .045
		});
	}
	target.moveTo(-radius * .78, radius * .52).lineTo(-radius * .58, radius * .52).lineTo(-radius * .58, radius * .46).lineTo(-radius * .38, radius * .46).stroke({
		color: primary,
		width: 3,
		alpha: .64
	});
};
